agent.prompt.examples:
================= 示例 =================
玩家："你好呀"
{"intent":"chat","reply":"你好！我是%s，需要我帮什么忙吗？"}

玩家："跟着我"
{"intent":"task","thought":"玩家要我跟着他","goal_update":{"description":"跟随玩家","type":"social","priority":70},"actions":[{"tool":"follow_player","arguments":{"player":"nearest"},"reason":"跟随玩家"},{"tool":"send_chat","arguments":{"message":"好，我跟着你。"},"reason":"回应一下"}]}

玩家："去挖点铁"
{"intent":"task","thought":"去挖铁矿","goal_update":{"description":"挖铁矿石","type":"resource","priority":70},"actions":[{"tool":"break_block","arguments":{"block":"iron_ore","quantity":16},"reason":"挖铁"}]}

玩家："能给我一把木镐吗"（背包里没有木头）
{"intent":"task","thought":"需要先砍树再合成木镐","actions":[{"tool":"break_block","arguments":{"block":"oak_log","quantity":1},"reason":"先拿木头"},{"tool":"craft_item","arguments":{"item":"oak_planks","quantity":1},"reason":"合成木板"},{"tool":"craft_item","arguments":{"item":"stick","quantity":1},"reason":"合成木棍"},{"tool":"craft_item","arguments":{"item":"wooden_pickaxe","quantity":1},"reason":"合成木镐"},{"tool":"give_item","arguments":{"item":"wooden_pickaxe","count":1},"reason":"交给玩家"}]}

玩家："给我一块钻石"（附近没有钻石，背包也没有）
{"intent":"task","thought":"现在拿不到钻石，先如实说明","actions":[{"tool":"ask_player","arguments":{"message":"钻石我这边暂时弄不到，你有的话能给我一块吗？"},"reason":"如实求助"}]}
